from backend import config
from backend.meta import client
from backend.schemas import Scene


def render_machine(scene: Scene) -> bytes:
    prompt = "A clean technical illustration of a successful hand-built marble machine with " + ", ".join(part.type for part in scene.parts) + ". Warm paper background, clear mechanism, no text."
    if config.META_API_KEY:
        return client.generate_image(prompt)
    # Offline placeholder is intentionally a valid tiny PNG generated by Pillow.
    from PIL import Image, ImageDraw
    image = Image.new("RGB", (800, 500), "#f5ead7")
    draw = ImageDraw.Draw(image)
    draw.text((24, 24), "Sketch2Sim: verified machine", fill="#342d27")
    for part in scene.parts:
        shape = part.shape
        if hasattr(shape, "x"):
            draw.ellipse((shape.x-12, 500-shape.y-12, shape.x+12, 500-shape.y+12), fill="#d06b43")
        elif hasattr(shape, "a"):
            draw.line((shape.a[0], 500-shape.a[1], shape.b[0], 500-shape.b[1]), fill="#342d27", width=8)
    from io import BytesIO
    output = BytesIO()
    image.save(output, "PNG")
    return output.getvalue()
